def _is_chat_member_active(chat_member: object) -> bool:
    """Определяет, является ли участник активным в группе.

    Статус 'restricted' в Telegram двойственный:
    - is_member=True — пользователь в группе, но ограничен (mute/restrict)
    - is_member=False — пользователь забанен/кикнут

    Аргументы:
        chat_member: объект ChatMember с атрибутами status и is_member

    Возвращает:
        bool: True если участник фактически состоит в группе
    """
    status = chat_member.status
    if status in _SIMPLE_ACTIVE_STATUSES:
        return True
    if status == "restricted":
        return getattr(chat_member, "is_member", False)
    return False

